let hasTicket = false;

console.log("AND (both needed):", isAdult && hasTicket);
console.log("OR (at least one):", isAdult || hasTicket);
console.log("NOT (!isAdult):", !isAdult);

// Short-circuit evaluation
let fallbackName = "" || "Default User";
console.log("Fallback with OR:", fallbackName);
FULL_CODE_END -->

# Nullish Coalescing (`??`) 🛡️

The `??` operator returns its right-hand operand only when its left-hand operand is `null` or `undefined`.

Unlike `||`, it does **not** treat `0`, `false`, or `""` as missing!

```javascript
let userScore = 0;

// Bug with ||: treats 0 as falsy and replaces it with 10!
let resultA = userScore || 10; // 10 (Wrong!)

// Fixed with ??: preserves valid 0!
let resultB = userScore ?? 10; // 0 (Correct!)
```

