let userNickname = "";

console.log("Result with ||:", userScore || 10);
console.log("Result with ??:", userScore ?? 10);

console.log("Empty string with ||:", userNickname || "Anonymous");
console.log("Empty string with ??:", userNickname ?? "Anonymous");
